def canon(cells):
  forms=[]
  for refl in [1,-1]:
   for rot in range(4):
    pts=[]
    for r,c in cells:
     x,y=r,c*refl
     for _ in range(rot): x,y=y,-x
     pts.append((x,y))
    a=min(x for x,y in pts); b=min(y for x,y in pts)
    forms.append(tuple(sorted((x-a,y-b) for x,y in pts)))
  return min(forms)
